const config = {
  "previewFeatures": [],
  "clientVersion": "7.8.0",
  "engineVersion": "3c6e192761c0362d496ed980de936e2f3cebcd3a",
  "activeProvider": "postgresql",
  "inlineSchema": "// ============================================================\n// FieldCompliance — Prisma Schema\n// Multi-tenant oilfield environmental compliance platform\n// ============================================================\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// ============================================================\n// ENUMS\n// ============================================================\n\nenum UserRole {\n  ORG_ADMIN // manages billing, users, all facilities\n  EHS_COORDINATOR // full data entry + report generation\n  SITE_MANAGER // scoped to assigned facilities\n  FIELD_TECH // mobile entry only\n  AUDITOR // read-only across org\n}\n\nenum FacilityType {\n  PRODUCTION_WELL\n  INJECTION_WELL\n  COMPRESSOR_STATION\n  GATHERING_PIPELINE\n  PROCESSING_PLANT\n  STORAGE_TANK_BATTERY\n  MIDSTREAM_FACILITY\n}\n\nenum EquipmentCategory {\n  PNEUMATIC_CONTROLLER\n  PNEUMATIC_PUMP\n  STORAGE_TANK\n  SEPARATOR\n  COMPRESSOR_RECIPROCATING\n  COMPRESSOR_CENTRIFUGAL\n  DEHYDRATOR_GLYCOL\n  METER_SEPARATOR\n  FLARE_SYSTEM\n  WELLHEAD\n  FUGITIVE_COMPONENT\n}\n\nenum EmissionSource {\n  VENTING\n  FUGITIVE\n  COMBUSTION\n  FLARING\n  PROCESS_UPSET\n}\n\nenum RegulationJurisdiction {\n  FEDERAL_EPA\n  TEXAS_TCEQ\n  OKLAHOMA_DEQ\n  NEW_MEXICO_NMED\n  COLORADO_COGCC\n  WYOMING_DEQ\n  NORTH_DAKOTA_DEH\n}\n\nenum ReportStatus {\n  DRAFT\n  IN_REVIEW\n  SUBMITTED\n  ACCEPTED\n  REJECTED\n  AMENDED\n}\n\nenum DeadlineStatus {\n  PENDING\n  IN_PROGRESS\n  COMPLETED\n  OVERDUE\n  WAIVED\n}\n\nenum AuditAction {\n  CREATE\n  UPDATE\n  DELETE\n  EXPORT\n  SUBMIT\n  LOGIN\n  PERMISSION_CHANGE\n}\n\n// ============================================================\n// MULTI-TENANCY — Organizations\n// ============================================================\n\nmodel Organization {\n  id              String    @id @default(cuid())\n  name            String\n  slug            String    @unique\n  dotNumber       String?\n  epaReporterCode String?\n  taxId           String?\n  billingEmail    String\n  planTier        String    @default(\"starter\")\n  maxFacilities   Int       @default(10)\n  trialEndsAt     DateTime?\n  subscriptionId  String?\n  isActive        Boolean   @default(true)\n  createdAt       DateTime  @default(now())\n  updatedAt       DateTime  @updatedAt\n\n  users       User[]\n  facilities  Facility[]\n  regulations OrgRegulation[]\n  reports     ComplianceReport[]\n  auditLogs   AuditLog[]\n  apiKeys     ApiKey[]\n\n  @@index([slug])\n}\n\n// ============================================================\n// USERS\n// ============================================================\n\nmodel User {\n  id               String    @id @default(cuid())\n  orgId            String\n  email            String    @unique\n  firstName        String\n  lastName         String\n  role             UserRole  @default(FIELD_TECH)\n  phone            String?\n  isActive         Boolean   @default(true)\n  lastLoginAt      DateTime?\n  resetToken       String?\n  resetTokenExpiry DateTime?\n  createdAt        DateTime  @default(now())\n  updatedAt        DateTime  @updatedAt\n\n  org               Organization   @relation(fields: [orgId], references: [id])\n  facilityAccess    UserFacility[]\n  auditLogs         AuditLog[]\n  inspections       Inspection[]\n  assignedDeadlines Deadline[]\n\n  @@index([orgId])\n  @@index([email])\n}\n\nmodel UserFacility {\n  userId     String\n  facilityId String\n  grantedAt  DateTime @default(now())\n\n  user     User     @relation(fields: [userId], references: [id])\n  facility Facility @relation(fields: [facilityId], references: [id])\n\n  @@id([userId, facilityId])\n}\n\n// ============================================================\n// FACILITIES & EQUIPMENT\n// ============================================================\n\nmodel Facility {\n  id               String       @id @default(cuid())\n  orgId            String\n  name             String\n  type             FacilityType\n  apiWellNumber    String?\n  state            String\n  county           String?\n  latitude         Decimal?     @db.Decimal(10, 7)\n  longitude        Decimal?     @db.Decimal(10, 7)\n  legalDescription String?\n  operatorId       String?\n  isActive         Boolean      @default(true)\n  commissionedAt   DateTime?\n  decommissionedAt DateTime?\n  createdAt        DateTime     @default(now())\n  updatedAt        DateTime     @updatedAt\n\n  org             Organization       @relation(fields: [orgId], references: [id])\n  equipment       Equipment[]\n  userAccess      UserFacility[]\n  inspections     Inspection[]\n  deadlines       Deadline[]\n  emissionRecords EmissionRecord[]\n  reports         ComplianceReport[]\n\n  @@index([orgId])\n  @@index([state])\n  @@index([orgId, isActive])\n}\n\nmodel Equipment {\n  id              String            @id @default(cuid())\n  facilityId      String\n  tag             String\n  category        EquipmentCategory\n  description     String?\n  manufacturer    String?\n  model           String?\n  serialNumber    String?\n  installDate     DateTime?\n  lastServiceDate DateTime?\n  isActive        Boolean           @default(true)\n\n  // Emission-relevant attributes per equipment type\n  pneumaticType    String? // high-bleed | low-bleed | instrument\n  tankCapacityBbls Decimal? @db.Decimal(10, 2)\n  compressorHp     Int?\n  throughputMcfd   Decimal? @db.Decimal(10, 2)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  facility        Facility         @relation(fields: [facilityId], references: [id])\n  emissionRecords EmissionRecord[]\n  inspections     Inspection[]\n\n  @@unique([facilityId, tag])\n  @@index([facilityId])\n  @@index([facilityId, category])\n}\n\n// ============================================================\n// REGULATIONS — Versioned rules engine\n// ============================================================\n\nmodel Regulation {\n  id                 String                 @id @default(cuid())\n  code               String                 @unique\n  title              String\n  jurisdiction       RegulationJurisdiction\n  cfrPart            String?\n  federalRegisterUrl String?\n  description        String?\n  isActive           Boolean                @default(true)\n\n  versions       RegulationVersion[]\n  orgRegulations OrgRegulation[]\n\n  @@index([jurisdiction])\n}\n\nmodel RegulationVersion {\n  id            String    @id @default(cuid())\n  regulationId  String\n  version       String\n  effectiveDate DateTime\n  expiresAt     DateTime?\n  changeNotes   String?\n  rawJsonSchema Json\n  createdAt     DateTime  @default(now())\n\n  regulation   Regulation       @relation(fields: [regulationId], references: [id])\n  requirements RegulationRule[]\n  deadlines    Deadline[]\n\n  @@index([regulationId, effectiveDate])\n}\n\nmodel RegulationRule {\n  id                  String             @id @default(cuid())\n  regulationVersionId String\n  ruleCode            String\n  title               String\n  description         String\n  equipmentCategory   EquipmentCategory?\n  emissionSource      EmissionSource?\n  requirementType     String // SURVEY | REPORT | CALCULATE | RECORD | SUBMIT\n  frequencyDays       Int?\n  thresholdValue      Decimal?           @db.Decimal(10, 4)\n  thresholdUnit       String? // tpy | scfd | ppm\n  deadlineOffsetDays  Int?\n  penaltyPerDay       Decimal?           @db.Decimal(10, 2)\n  notes               String?\n\n  regulationVersion RegulationVersion @relation(fields: [regulationVersionId], references: [id])\n\n  @@index([regulationVersionId])\n  @@index([equipmentCategory])\n}\n\nmodel OrgRegulation {\n  orgId        String\n  regulationId String\n  enrolledAt   DateTime @default(now())\n  enrolledBy   String?\n  notes        String?\n\n  org        Organization @relation(fields: [orgId], references: [id])\n  regulation Regulation   @relation(fields: [regulationId], references: [id])\n\n  @@id([orgId, regulationId])\n}\n\n// ============================================================\n// DEADLINES — Core daily-use feature\n// ============================================================\n\nmodel Deadline {\n  id                  String         @id @default(cuid())\n  orgId               String\n  facilityId          String\n  regulationVersionId String\n  ruleCode            String\n  title               String\n  description         String?\n  dueDate             DateTime\n  periodStart         DateTime?\n  periodEnd           DateTime?\n  status              DeadlineStatus @default(PENDING)\n  assignedUserId      String?\n  completedAt         DateTime?\n  completedBy         String?\n  notes               String?\n  createdAt           DateTime       @default(now())\n  updatedAt           DateTime       @updatedAt\n\n  facility          Facility          @relation(fields: [facilityId], references: [id])\n  regulationVersion RegulationVersion @relation(fields: [regulationVersionId], references: [id])\n  assignedUser      User?             @relation(fields: [assignedUserId], references: [id])\n  alerts            DeadlineAlert[]\n\n  @@index([orgId, status])\n  @@index([orgId, dueDate])\n  @@index([facilityId])\n}\n\nmodel DeadlineAlert {\n  id          String    @id @default(cuid())\n  deadlineId  String\n  alertType   String // EMAIL | SMS | IN_APP\n  scheduledAt DateTime\n  sentAt      DateTime?\n  recipient   String\n  channel     String // sendgrid | twilio | internal\n\n  deadline Deadline @relation(fields: [deadlineId], references: [id])\n\n  @@index([deadlineId])\n  @@index([scheduledAt, sentAt])\n}\n\n// ============================================================\n// INSPECTIONS — Offline-capable field data entry\n// ============================================================\n\nmodel Inspection {\n  id                String    @id @default(cuid())\n  facilityId        String\n  equipmentId       String?\n  inspectorId       String\n  inspectionType    String // OGI | METHOD_21 | VISUAL | AVO | LDAR_SURVEY\n  conductedAt       DateTime\n  weatherConditions String?\n  windSpeedMph      Decimal?  @db.Decimal(5, 1)\n  ambientTempF      Decimal?  @db.Decimal(5, 1)\n  findings          String?\n  leakDetected      Boolean   @default(false)\n  repairDeadline    DateTime?\n  repairedAt        DateTime?\n  photoUrls         String[]\n  gpsLat            Decimal?  @db.Decimal(10, 7)\n  gpsLng            Decimal?  @db.Decimal(10, 7)\n  syncedAt          DateTime?\n  createdAt         DateTime  @default(now())\n  updatedAt         DateTime  @updatedAt\n\n  facility  Facility   @relation(fields: [facilityId], references: [id])\n  equipment Equipment? @relation(fields: [equipmentId], references: [id])\n  inspector User       @relation(fields: [inspectorId], references: [id])\n\n  @@index([facilityId, conductedAt])\n  @@index([inspectorId])\n}\n\n// ============================================================\n// EMISSIONS — Calculated records\n// ============================================================\n\nmodel EmissionRecord {\n  id                   String         @id @default(cuid())\n  facilityId           String\n  equipmentId          String?\n  reportingPeriodStart DateTime\n  reportingPeriodEnd   DateTime\n  emissionSource       EmissionSource\n  pollutant            String // CH4 | CO2 | N2O | VOC | NOx\n  calculationMethod    String // AP42 | SITE_SPECIFIC | OGI_MEASUREMENT | ENGINEERING_EST\n  emissionFactorId     String?\n  activityData         Json\n  calculatedQuantity   Decimal        @db.Decimal(14, 4)\n  unit                 String // tpy | scf | mt-CO2e\n  co2Equivalent        Decimal?       @db.Decimal(14, 4)\n  verifiedAt           DateTime?\n  verifiedBy           String?\n  notes                String?\n  createdAt            DateTime       @default(now())\n  updatedAt            DateTime       @updatedAt\n\n  facility       Facility        @relation(fields: [facilityId], references: [id])\n  equipment      Equipment?      @relation(fields: [equipmentId], references: [id])\n  emissionFactor EmissionFactor? @relation(fields: [emissionFactorId], references: [id])\n\n  @@index([facilityId, reportingPeriodStart])\n  @@index([facilityId, pollutant])\n}\n\n// EPA-approved emission factors — seeded from AP-42, OOOOb, Subpart W tables\nmodel EmissionFactor {\n  id                 String            @id @default(cuid())\n  source             String // AP42 | OOOOb | SUBPART_W | SITE_SPECIFIC\n  equipmentCategory  EquipmentCategory\n  pollutant          String\n  factorValue        Decimal           @db.Decimal(14, 6)\n  factorUnit         String // scf-CH4/hr | tpy/unit | lb/MMscf\n  applicableFrom     DateTime\n  applicableUntil    DateTime?\n  notes              String?\n  federalRegCitation String?\n\n  emissionRecords EmissionRecord[]\n\n  @@index([equipmentCategory, pollutant])\n}\n\n// ============================================================\n// REPORTS — Generated compliance submissions\n// ============================================================\n\nmodel ComplianceReport {\n  id                  String       @id @default(cuid())\n  orgId               String\n  facilityId          String?\n  reportType          String // SUBPART_W | OOOOb | TCEQ_ANNUAL | CUSTOM\n  reportingYear       Int\n  periodStart         DateTime\n  periodEnd           DateTime\n  status              ReportStatus @default(DRAFT)\n  generatedAt         DateTime?\n  submittedAt         DateTime?\n  submittedBy         String?\n  eggrtConfirmationId String?\n  xmlPayload          String?\n  pdfS3Key            String?\n  reviewNotes         String?\n  createdAt           DateTime     @default(now())\n  updatedAt           DateTime     @updatedAt\n\n  org      Organization @relation(fields: [orgId], references: [id])\n  facility Facility?    @relation(fields: [facilityId], references: [id])\n\n  @@index([orgId, reportingYear])\n  @@index([orgId, status])\n}\n\n// ============================================================\n// AUDIT LOG — Immutable, append-only\n// ============================================================\n\nmodel AuditLog {\n  id          String      @id @default(cuid())\n  orgId       String\n  userId      String?\n  action      AuditAction\n  entityType  String\n  entityId    String\n  beforeState Json?\n  afterState  Json?\n  ipAddress   String?\n  userAgent   String?\n  metadata    Json?\n  createdAt   DateTime    @default(now())\n\n  org  Organization @relation(fields: [orgId], references: [id])\n  user User?        @relation(fields: [userId], references: [id])\n\n  @@index([orgId, createdAt])\n  @@index([entityType, entityId])\n  @@index([userId, createdAt])\n}\n\n// ============================================================\n// API KEYS — Consultant / third-party access\n// ============================================================\n\nmodel ApiKey {\n  id         String    @id @default(cuid())\n  orgId      String\n  name       String\n  keyHash    String    @unique\n  prefix     String\n  scopes     String[]\n  lastUsedAt DateTime?\n  expiresAt  DateTime?\n  isActive   Boolean   @default(true)\n  createdAt  DateTime  @default(now())\n\n  org Organization @relation(fields: [orgId], references: [id])\n\n  @@index([orgId])\n}\n"
}

